233→async function findReplaceString(html, signer_order, replace) {
234→    const $ = cheerio.load(html);
235→    const searchString = `[$FIRMA${signer_order}]`;
236→
237→    $("div.new-signature").each(function () {
238→        const $this = $(this);
239→        const divContent = $this.html();
240→
241→        if (divContent.includes(searchString)) {
242→            const next = $this.next();
243→            if (next.hasClass("new-modified_content")) {
244→                next.remove();
245→            }
246→
247→            $this.replaceWith(replace);
248→        }
249→    });
250→
251→    return $.html();
252→}
