 44→                select: {
 45→                    company_name: true,
 46→                },
 47→            },
 48→        },
 49→    });
 50→
 51→    for (const assignment of assignments) {
 52→        let percentage = 0;
 53→        let message = '';
 54→        let package_type = '';
 55→
 56→        if (assignment.package_id === 1) {
 57→            if (assignment.units && assignment.remaining_units === 0) {
 58→                percentage = 100;
 59→                message = `Te informamos que tu paquete ha agotado todas sus unidades.`;
 60→                package_type = 'paquete de unidades';
 61→            } else if (assignment.units) {
 62→                const usedUnits = assignment.units - assignment.remaining_units;
 63→                percentage = (usedUnits / assignment.units) * 100;
 64→            }
 65→        } else if (assignment.package_id === 2) {
 66→            if (assignment.end_date && moment(assignment.end_date).isBefore(today)) {
 67→                percentage = 100;
 68→                message = `Te queremos informar que el tiempo de tu paquete ilimitado ha caducado.`;
