 71→                const startDate = moment(assignment.start_date).startOf('day');
 72→                const endDate = moment(assignment.end_date).startOf('day');
 73→                const totalDays = endDate.diff(startDate, 'days');
 74→                const elapsedDays = today.diff(startDate, 'days');
 75→                percentage = (elapsedDays / totalDays) * 100;
 76→            }
 77→        }
 78→
 79→        const flooredPercentage = Math.floor(percentage);
 80→
 81→        if (flooredPercentage >= 100) {
