 89→            );
 90→            await prisma.company_packages_assignments.update({
 91→                where: { id: assignment.id },
 92→                data: { notification_sent: true },
 93→            });
 94→        }
 95→    }
 96→
 97→    console.log("Chequeo de paquetes completado.");
 98→};
