"use strict";

const { PrismaClient } = require('@prisma/client');
const moment = require('moment');
require('moment/locale/es'); // Configura idioma español
const service = require("../services");
const Queue = require("bull");
const db = new PrismaClient();

const sendRemindersQueue = new Queue("send-reminders-queue", {
    redis: { host: "127.0.0.1", port: 6379 },
});
console.log("Queue 'send-reminders-queue' inicializada.");


const checkReminders = async () => {
    const today = moment().tz('America/Bogota').startOf('day'); 
    const reminders = await db.document_packages_signers.findMany({
        select: {
            id: true,
            send_reminder: true,
            reminder_days_interval: true,
            last_reminder_sent_at: true,
            next_reminder_at: true,
            status: true,
            company: {
                select: {
                    avatar: true,
                    fiscal_name: true,
                    email: true,
                },
            },
            document_packages_header: {
                select: {
                   name: true,
                },
            },
            documents: {
                take: 1,
                select: {
                    name: true,
                },
            },
            signers: {
                select: {
                    id: true,
                    token: true,
                    status: true,
                    expires_in_days: true, 
                    sent_sign_request_at: true,
                    users: {
                        select: {
                            firstname: true,
                            lastname: true,
                            email: true,
                        },
                    },
                },
                where: {
                    status: "send",
                }
            },
        },
        where: {
            send_reminder: true, 
            status: "send", 
        },
    });

    for (const reminder of reminders) {
        const { id, reminder_days_interval, next_reminder_at, signers } = reminder;

        if (next_reminder_at && moment(next_reminder_at).tz('America/Bogota').isAfter(today)) {
            console.log(`El recordatorio para el paquete ${id} ya está programado para otro día.`);
            continue; 
        }

        for (const signer of signers) {
            const { id: signerId, expires_in_days, users } = signer;

            if (!expires_in_days || !reminder_days_interval || reminder_days_interval <= 0) {
                console.warn(`Recordatorio inválido para signer ID: ${signerId}, falta configuración.`);
                continue;
            }

            const expirationDate = moment(expires_in_days).utc().tz('America/Bogota').startOf('day');
            const daysUntilExpiration = expirationDate.diff(today, 'days');

            if (expirationDate.hour() < 5) {
                expirationDate.add(1, 'days'); 
            }


            if (daysUntilExpiration < 0) {
                console.warn(`El documento del signer ID: ${signerId} ya expiró.`);
                continue;
            }

            if (daysUntilExpiration <= reminder_days_interval) {
                const { email, firstname, lastname } = users || {};

                if (!email) {
                    console.warn(`Falta el correo electrónico para signer ID: ${signerId}`);
                    continue;
                }

                try {


                    const _url = process.env.ENV_URL + signer.token;
                    let date = expirationDate.format('DD/MM/YYYY');  
                    let time = expirationDate.format('hh:mm A');  


                    await service.sendReminderRequest(
                        email,
                        reminder.company.avatar,
                        `${firstname} ${lastname}`,
                        reminder.company.fiscal_name,
                        date,
                        time,
                        _url,
                        reminder.company.company_email,
                        reminder.document_packages_header?.name || reminder.documents[0]?.name,
                    );

                    const nextReminder = moment(today).tz('America/Bogota').add(1, 'days');

                    await db.document_packages_signers.update({
                        where: { id },
                        data: {
                            last_reminder_sent_at: today.toDate(),
                            next_reminder_at: nextReminder.toDate(),
                        },
                    });


                } catch (error) {
                    console.error(`Error al procesar el envío a ${email}:`, error);
                }
            }
        }
    }
};

/* (async () => {
    console.log("Agregando trabajo manual a la cola...");
    await sendRemindersQueue.add({});
})(); */

sendRemindersQueue.process(async () => {
    console.log("Ejecutando el job de Bull para notificaciones preventivas...");
    await checkReminders();
});

sendRemindersQueue.add({}, { repeat: { cron: "0 17 * * *" } });

module.exports = sendRemindersQueue;

