        const uniqueSignerNumbers = new Set();

        for (const pdfId in this.allPdfFields) {
            const fields = this.allPdfFields[pdfId] || [];

            fields.forEach(field => {
                if (field.type === 'signature' && field.name) {
                    const match = field.name.match(/\[\$FIRMA(\d+)\]/);

                    if (match) {
                        uniqueSignerNumbers.add(match[1]);
                    }
                }
            });
