      const a = document.createElement('a');
      a.href = blobUrl;
      a.download = `Plantilla del grupo ${selectedValue.name}_${moment().format('DD-MM-YYYY h-m-s')}`;
      a.style.display = 'none';

      document.body.appendChild(a);
      a.click();

      window.URL.revokeObjectURL(blobUrl);
      document.body.removeChild(a);    
    },

    submitForm() {
      if (this.$refs.submitForm.validate()) {
        this.$emit('submit-form', { excel_file: this.excel_file, fields: this.fields, countryId: this.selectedCountry || 1 });
      }
    },
    async getCountries () {
        try {

            const response = await this.$axios({
                method: 'GET',
                url: '/get_countries',
            }); 

            this.countries = response.data;
            this.selectedCountry = this.$state.auth_user.data.company_country_id || 1; 

        } catch (error) {
            console.error(error);
        }
    },
  },
};
</script>

